1	#ifndef SG_FUSED_SM90_DEC_WEIGHTS_CUH_
2	#define SG_FUSED_SM90_DEC_WEIGHTS_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/dec_weights.cuh — REAL transformer-decoder weight binding +
5	// fp32 in-kernel forward/backward stage substrate, SALVAGED VERBATIM from the
6	// former csrc/fused/sm_90/model_stages_decoder.cuh during the eager/scalar/
7	// surrogate removal (task #10). The eager element-local SURROGATE substrate
8	// (model_stages.cuh / fused_megakernel.cuh) and the 33 surrogate mega_*.cu
9	// cells were deleted; this file is the genuine decoder substrate that the KEPT
10	// L3-TC path still depends on and was kept (not deleted) for that reason.
11	//
12	// KEPT CONSUMERS (why every symbol below is still live):
13	//   * model_stage_decoder_tc.cuh — reuses dec::* shape constants, dec::attn_scale,
14	//     dec::kLnEps, DecWeights/DecWeights::Layer, DecGrad, dec_gelu/dec_gelu_grad,
15	//     dec_block_sum/dec_block_max (the TC engine's own fwd/bwd reuse these prims).
16	//   * fused_decoder_megakernel.cuh — its TC driver uses dec::* shape constants;
17	//     and its fp32 scalar megakernel (the `#if SG_DEC_SCALAR_MEGAKERNEL` block,
18	//     DEFAULT ON) uses DecSampleSmem + dec_bind/dec_bind_grad + dec_forward_sample
19	//     + dec_backward_sample. So the full fwd/bwd stages below are NOT dead while
20	//     that block compiles — they are part of the kept include graph.
21	//   * pp_stage_decoder_tc.cuh, decoder_tc_selftest.cu, tp_layer.cuh reach these
22	//     symbols transitively through the two headers above.
23	// NOTE: this is the genuine eager-architecture decoder (the REAL math), NOT a
24	// surrogate — there is no GELU(param+input) element-local surrogate in this file
25	// to drop; that surrogate lived only in the deleted model_stages.cuh.
26	//
27	// HONESTY: this is the genuine eager architecture (grokking_race_v2.py
28	// _raw_model → Transformer), transcribed LINE-FOR-LINE from the verified
29	// PyTorch oracle in tests/hw/decoder_oracle.py, which is asserted bit-identical
30	// (fp64, ~1e-15 rel) to torch.autograd for the loss and EVERY one of the 30
31	// parameter gradients. There is NO placeholder math on this path. The one
32	// deliberate, documented deviation from the oracle is execution mechanics, not
33	// numerics: the backward RECOMPUTES each layer's forward from the cached layer
34	// INPUT (rather than caching every intermediate) to keep only one layer's
35	// activations live in smem at a time — see the smem-budget note below. The math
36	// computed is identical; only the storage strategy differs.
37	//
38	// ARCHITECTURE (exact; cites grokking_race_v2.py lines):
39	//   Transformer(nl=2, d=128, h=4, ntok=99, seq=4)  [_raw_model hardcodes seq=4]
40	//     tok = Embedding(99,128) (:360) + pos = Embedding(4,128) (:360)
41	//     2 × DecoderBlock (:346):
42	//       attn = MultiheadAttention(128,4,batch_first) (:349), causal mask
43	//              triu(diag=1) (:352): pos i attends j<=i
44	//       n1,n2 = LayerNorm(128) (:350), eps=1e-5 (torch default)
45	//       ff = Linear(128,512) → GELU(exact erf) → Linear(512,128) (:351)
46	//       POST-LN: x=n1(x+attn(x)); h=n2(x+ff(x))  (:354-355)
47	//     norm = LayerNorm(128) (:362); out = Linear(128,99) (:362)
48	//     forward: h=tok+pos; for l: h=l(h); return out(norm(h)[:,-1,:]) (:366-368)
49	//   loss = cross_entropy(logits, targets) (mean over batch; :745).
50	//
51	// NUMERICS (verified in the oracle; see decoder_oracle.py):
52	//   * GELU = exact erf  0.5x(1+erf(x/√2)); grad 0.5(1+erf(x/√2))+x·φ(x),
53	//     φ(x)=(1/√(2π))e^{-x²/2}.  (The surrogate's tanh approx is ~4e-4 off and
54	//     would blow the 1e-4 grad tolerance — NOT used here.)
55	//   * LayerNorm eps = 1e-5; dx uses the two mean-correction terms.
56	//   * attention scale 1/√dh = 1/√32; softmax subtracts the row max.
57	//   * cross-entropy MEAN over B → dlogits = (softmax−onehot)/B.
58	//
59	// PARALLELIZATION (locked design — Option B, batch-parallel, deterministic):
60	//   * Each CTA owns a FIXED contiguous batch slice (by blockIdx.x — NOT the
61	//     work-stealing task queue, which is param-tensor-parallel and would vary
62	//     the batch→CTA grouping; fp32 sums are not associative so a varying
63	//     grouping is non-deterministic). The whole CTA cooperates on ONE sample at
64	//     a time and iterates its slice SEQUENTIALLY.
65	//   * Per-sample, the CTA accumulates that sample's weight-grad contribution
66	//     into the CTA's OWN partial buffer in the global workspace
67	//     (gw + cta*total). Each dW element has a SINGLE owner thread that does
68	//     partial[e] += contrib across the slice's samples in fixed order
69	//     (__syncthreads between samples) — single-writer, no atomics, deterministic.
70	//   * One grid barrier, then a deterministic cross-CTA reduce: sum
71	//     partial[0..nCTA) in ASCENDING CTA index into the global grad buffer
72	//     (determinism lives in the per-element summation ORDER, not who computes it
73	//     — so the reduce REUSES the work-steal queue: whichever CTA grabs a param
74	//     element-range sums the partials for it in ascending CTA order).
75	//   * Another grid barrier, then the existing apply_optimizer<AdamW> tail
76	//     consumes the reduced grad in place.
77	//   * Loss: each CTA sums its slice's NLL (fp32) into a per-CTA loss slot; the
78	//     reduce sums those in fp64 and divides by B → one device float (the 1e-5
79	//     loss rel-tol is the tightest gate; fp32 atomic-summing 4191 terms misses it).
80	//
81	// SMEM BUDGET PER CTA (one sample, one layer live; recompute-in-backward):
82	//   The dominant per-sample buffer is the FFN hidden ff0/g [S=4 × 4d=512] =
83	//   2048 floats = 8 KB. With the QKV [4×384], ctx/x1/residual [4×128] and the LN
84	//   caches, one layer's live working set is ~25 KB — UNDER the 48 KB static-smem
85	//   cliff, so NO dynamic-smem opt-in is needed and the occupancy≥1 launch guard
86	//   in fused_megakernel.cuh (dynamicSMemBytes=0) is unchanged. Caching BOTH
87	//   layers (~50 KB) would cross 48 KB and force cudaFuncSetAttribute — avoided by
88	//   the per-layer recompute. The flat smem arena below is sized accordingly.
89	// ============================================================================
90	
91	#include "csrc/fused/megakernel_common.cuh"
92	#include "csrc/fused/sm_90/decoder_layout.cuh"
93	#include <cuda_runtime.h>
94	#include <cstdint>
95	#include <math_constants.h>
96	
97	namespace sg { namespace fused { namespace sm90 {
98	
99	// ── Decoder compile-time shape constants (mirror tests/hw/decoder_oracle.py and
100	//    csrc/fused/sm_90/decoder_layout.cuh; static_asserts there guard the count
101	//    + total against named_parameters()). ─────────────────────────────────────
102	namespace dec {
103	constexpr int kVocab  = SG_DEC_VOCAB;   // 99
104	constexpr int kD      = SG_DEC_D;       // 128
105	constexpr int kHeads  = SG_DEC_HEADS;   // 4
106	constexpr int kLayers = SG_DEC_LAYERS;  // 2
107	constexpr int kSeq    = SG_DEC_SEQ;     // 4
108	constexpr int kDff    = SG_DEC_DFF;     // 512
109	constexpr int kDhead  = kD / kHeads;    // 32
110	constexpr float kLnEps = 1e-5f;         // torch LayerNorm default
111	// Attention scale 1/sqrt(dhead). rsqrtf is fine; keep it a constexpr-ish value
112	// computed once on host-visible compile (1/sqrt(32)).
113	__device__ __forceinline__ float attn_scale() { return rsqrtf((float)kDhead); }
114	}  // namespace dec
115	
116	// ── Exact-erf GELU + derivative (the real nn.GELU(), NOT the tanh surrogate). ──
117	__device__ __forceinline__ float dec_gelu(float x) {
118	    // 0.5 x (1 + erf(x/sqrt2)).  M_SQRT1_2 = 1/sqrt(2).
119	    return 0.5f * x * (1.0f + erff(x * (float)M_SQRT1_2));
120	}
121	__device__ __forceinline__ float dec_gelu_grad(float x) {
122	    // 0.5(1+erf(x/√2)) + x · φ(x), φ(x) = (1/√(2π)) e^{-x²/2}.
123	    const float cdf = 0.5f * (1.0f + erff(x * (float)M_SQRT1_2));
124	    const float inv_sqrt_2pi = 0.39894228040143270286f;  // 1/sqrt(2*pi)
125	    const float pdf = inv_sqrt_2pi * __expf(-0.5f * x * x);
126	    return cdf + x * pdf;
127	}
128	
129	// ── Per-CTA scratch for one sample. POD held in smem (one instance per CTA).
130	//    Sizes chosen so the live set is one layer (recompute in backward). The
131	//    arrays that must survive fwd→bwd within a layer are kept; the rest are
132	//    recomputed. All [kSeq × width] row-major (row = position). ───────────────
133	struct DecSampleSmem {
134	    // Per-layer cached INPUT to each layer (h before the layer) — the only
135	    // cross-layer state kept, so the backward can recompute each layer's fwd.
136	    float layer_in[dec::kLayers][dec::kSeq][dec::kD];   // 2*4*128 = 1024 f
137	    // The final-norm input (last layer output, all positions) for bwd.
138	    float final_in[dec::kSeq][dec::kD];                 // 4*128 = 512 f
139	    // Scratch reused within a single layer's fwd or bwd (one layer live):
140	    float qkv[dec::kSeq][3 * dec::kD];                  // 4*384 = 1536 f
141	    float ctx[dec::kSeq][dec::kD];                      // 4*128 = 512 f
142	    float x1[dec::kSeq][dec::kD];                       // 4*128 = 512 f (post n1)
143	    float ff0[dec::kSeq][dec::kDff];                    // 4*512 = 2048 f (pre-gelu)
144	    float gact[dec::kSeq][dec::kDff];                   // 4*512 = 2048 f (post-gelu)
145	    float attn[dec::kHeads][dec::kSeq][dec::kSeq];      // 4*4*4 = 64 f
146	    // LayerNorm caches (xhat + inv_std) for n1, n2, final — per position.
147	    float n1_xhat[dec::kSeq][dec::kD];
148	    float n1_inv[dec::kSeq];
149	    float n2_xhat[dec::kSeq][dec::kD];
150	    float n2_inv[dec::kSeq];
151	    float fn_xhat[dec::kSeq][dec::kD];
152	    float fn_inv[dec::kSeq];
153	    // Backward adjoints carried across sub-steps (one layer live), per position.
154	    float dh[dec::kSeq][dec::kD];                       // running grad wrt block out
155	    float logits[dec::kVocab];                          // last-pos logits (bwd)
156	    // Dedicated attention-backward dscores buffer (NOT aliased over `attn`, so
157	    // the forward softmax weights stay live while dv/dq/dk read them). 64 f.
158	    float dsc[dec::kHeads][dec::kSeq][dec::kSeq];
159	    // Reductions across threads for row stats (mean / max / dot). 256 threads.
160	    float red[256];
161	};
162	
163	// A typed view over the flat weight blob using the generated offsets. All
164	// pointers are into the single global `params` buffer (read-only in fwd/bwd).
165	struct DecWeights {
166	    const float* tok;     // [kVocab, kD]
167	    const float* pos;     // [kSeq, kD]
168	    struct Layer {
169	        const float* in_w;   // [3d, d]
170	        const float* in_b;   // [3d]
171	        const float* out_w;  // [d, d]
172	        const float* out_b;  // [d]
173	        const float* n1_w;   // [d]
174	        const float* n1_b;   // [d]
175	        const float* n2_w;   // [d]
176	        const float* n2_b;   // [d]
177	        const float* ff0_w;  // [4d, d]
178	        const float* ff0_b;  // [4d]
179	        const float* ff2_w;  // [d, 4d]
180	        const float* ff2_b;  // [d]
181	    } layer[dec::kLayers];
182	    const float* norm_w;  // [d]
183	    const float* norm_b;  // [d]
184	    const float* out_w;   // [kVocab, d]
185	    const float* out_b;   // [kVocab]
186	};
187	
188	// Bind DecWeights to the flat params using the generated element offsets. The
189	// offsets array (csrc/fused/sm_90/decoder_layout.cuh::kDecOffsets) is the C++
190	// mirror of tests/hw/decoder_oracle.py::decoder_param_layout(), static-asserted.
191	__device__ __forceinline__ DecWeights dec_bind(const float* p) {
192	    DecWeights w;
193	    int i = 0;
194	    w.tok = p + kDecOffsets[i++];
195	    w.pos = p + kDecOffsets[i++];
196	    for (int li = 0; li < dec::kLayers; ++li) {
197	        w.layer[li].in_w  = p + kDecOffsets[i++];
198	        w.layer[li].in_b  = p + kDecOffsets[i++];
199	        w.layer[li].out_w = p + kDecOffsets[i++];
200	        w.layer[li].out_b = p + kDecOffsets[i++];
201	        w.layer[li].n1_w  = p + kDecOffsets[i++];
202	        w.layer[li].n1_b  = p + kDecOffsets[i++];
203	        w.layer[li].n2_w  = p + kDecOffsets[i++];
204	        w.layer[li].n2_b  = p + kDecOffsets[i++];
205	        w.layer[li].ff0_w = p + kDecOffsets[i++];
206	        w.layer[li].ff0_b = p + kDecOffsets[i++];
207	        w.layer[li].ff2_w = p + kDecOffsets[i++];
208	        w.layer[li].ff2_b = p + kDecOffsets[i++];
209	    }
210	    w.norm_w = p + kDecOffsets[i++];
211	    w.norm_b = p + kDecOffsets[i++];
212	    w.out_w  = p + kDecOffsets[i++];
213	    w.out_b  = p + kDecOffsets[i++];
214	    return w;
215	}
216	
217	// Identical helper for the per-CTA grad PARTIAL buffer (writable, same layout).
218	struct DecGrad {
219	    float* tok; float* pos;
220	    struct Layer { float* in_w; float* in_b; float* out_w; float* out_b;
221	        float* n1_w; float* n1_b; float* n2_w; float* n2_b;
222	        float* ff0_w; float* ff0_b; float* ff2_w; float* ff2_b; } layer[dec::kLayers];
223	    float* norm_w; float* norm_b; float* out_w; float* out_b;
224	};
225	__device__ __forceinline__ DecGrad dec_bind_grad(float* p) {
226	    DecGrad w; int i = 0;
227	    w.tok = p + kDecOffsets[i++];
228	    w.pos = p + kDecOffsets[i++];
229	    for (int li = 0; li < dec::kLayers; ++li) {
230	        w.layer[li].in_w  = p + kDecOffsets[i++];
231	        w.layer[li].in_b  = p + kDecOffsets[i++];
232	        w.layer[li].out_w = p + kDecOffsets[i++];
233	        w.layer[li].out_b = p + kDecOffsets[i++];
234	        w.layer[li].n1_w  = p + kDecOffsets[i++];
235	        w.layer[li].n1_b  = p + kDecOffsets[i++];
236	        w.layer[li].n2_w  = p + kDecOffsets[i++];
237	        w.layer[li].n2_b  = p + kDecOffsets[i++];
238	        w.layer[li].ff0_w = p + kDecOffsets[i++];
239	        w.layer[li].ff0_b = p + kDecOffsets[i++];
240	        w.layer[li].ff2_w = p + kDecOffsets[i++];
241	        w.layer[li].ff2_b = p + kDecOffsets[i++];
242	    }
243	    w.norm_w = p + kDecOffsets[i++];
244	    w.norm_b = p + kDecOffsets[i++];
245	    w.out_w  = p + kDecOffsets[i++];
246	    w.out_b  = p + kDecOffsets[i++];
247	    return w;
248	}
249	
250	// ── Block-wide reductions (256 threads) over a value `v`. The smem `red` slot
251	//    is the DecSampleSmem::red array. All threads must call. ──────────────────
252	__device__ __forceinline__ float dec_block_sum(float v, float* red) {
253	    const unsigned full = 0xffffffffu;
254	    #pragma unroll
255	    for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(full, v, o);
256	    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
257	    if (lane == 0) red[warp] = v;
258	    __syncthreads();
259	    const int nwarp = (blockDim.x + 31) >> 5;
260	    float r = 0.0f;
261	    if (warp == 0) {
262	        float p = (lane < nwarp) ? red[lane] : 0.0f;
263	        #pragma unroll
264	        for (int o = 16; o > 0; o >>= 1) p += __shfl_down_sync(full, p, o);
265	        if (lane == 0) red[0] = p;
266	    }
267	    __syncthreads();
268	    r = red[0];
269	    __syncthreads();
270	    return r;
271	}
272	__device__ __forceinline__ float dec_block_max(float v, float* red) {
273	    const unsigned full = 0xffffffffu;
274	    #pragma unroll
275	    for (int o = 16; o > 0; o >>= 1) {
276	        float other = __shfl_down_sync(full, v, o);
277	        v = fmaxf(v, other);
278	    }
279	    const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;
280	    if (lane == 0) red[warp] = v;
281	    __syncthreads();
282	    const int nwarp = (blockDim.x + 31) >> 5;
283	    float r;
284	    if (warp == 0) {
285	        float p = (lane < nwarp) ? red[lane] : -CUDART_INF_F;
286	        #pragma unroll
287	        for (int o = 16; o > 0; o >>= 1) {
288	            float other = __shfl_down_sync(full, p, o);
289	            p = fmaxf(p, other);
290	        }
291	        if (lane == 0) red[0] = p;
292	    }
293	    __syncthreads();
294	    r = red[0];
295	    __syncthreads();
296	    return r;
297	}
298	
299	// ────────────────────────────────────────────────────────────────────────────
300	//  Primitive in-kernel ops, CTA-cooperative over one sample. Inputs/outputs are
301	//  smem [kSeq, width] tiles. Threads stride over the (position, feature) grid.
302	//  These mirror the oracle's primitive ops exactly.
303	// ────────────────────────────────────────────────────────────────────────────
304	
305	// y[s, :out] = x[s, :in] @ W[out, in]^T + b[out].  W row-major [out, in].
306	// CTA-cooperative: one thread per (s, o) output element, strided.
307	__device__ __forceinline__ void dec_linear(
308	        const float* __restrict__ x, int in_dim,
309	        const float* __restrict__ W, const float* __restrict__ b, int out_dim,
310	        float* __restrict__ y) {
311	    const int total = dec::kSeq * out_dim;
312	    for (int idx = threadIdx.x; idx < total; idx += blockDim.x) {
313	        const int s = idx / out_dim;
314	        const int o = idx % out_dim;
315	        const float* xr = x + s * in_dim;
316	        const float* Wr = W + (int64_t)o * in_dim;
317	        float acc = (b != nullptr) ? b[o] : 0.0f;
318	        #pragma unroll 4
319	        for (int k = 0; k < in_dim; ++k) acc += xr[k] * Wr[k];
320	        y[s * out_dim + o] = acc;
321	    }
322	    __syncthreads();
323	}
324	
325	// LayerNorm forward over the last dim (width=d). Caches xhat + inv_std for bwd.
326	// gamma/beta are [d]. Per position: mean/var across d (cooperative reduce).
327	__device__ __forceinline__ void dec_layernorm_fwd(
328	        const float* __restrict__ x, const float* __restrict__ gamma,
329	        const float* __restrict__ beta, float* __restrict__ y,
330	        float* __restrict__ xhat_out, float* __restrict__ inv_out,
331	        float* red) {
332	    // Process positions sequentially (kSeq small); each is a full-CTA reduce.
333	    for (int s = 0; s < dec::kSeq; ++s) {
334	        const float* xr = x + s * dec::kD;
335	        float sum = 0.0f;
336	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += xr[j];
337	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
338	        float vs = 0.0f;
339	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
340	            float c = xr[j] - mean; vs += c * c;
341	        }
342	        float var = dec_block_sum(vs, red) / (float)dec::kD;
343	        float inv = rsqrtf(var + dec::kLnEps);
344	        if (threadIdx.x == 0) inv_out[s] = inv;
345	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
346	            float xh = (xr[j] - mean) * inv;
347	            xhat_out[s * dec::kD + j] = xh;
348	            y[s * dec::kD + j] = xh * gamma[j] + beta[j];
349	        }
350	        __syncthreads();
351	    }
352	}
353	
354	// ────────────────────────────────────────────────────────────────────────────
355	//  FORWARD for one sample (CTA-cooperative). `tokens_s` is this sample's kSeq
356	//  token ids (smem). Writes the per-layer input cache + final-norm input +
357	//  last-position logits into `sm`, and returns the sample NLL (all threads see
358	//  the same value). Recompute-friendly: the layer-local scratch (qkv/ctx/x1/
359	//  ff0/gact/attn + LN caches) reflects the LAST layer processed; backward
360	//  recomputes per layer from layer_in.
361	// ────────────────────────────────────────────────────────────────────────────
362	// `inline` (vague linkage) is REQUIRED, not optional: these dec_* helpers are
363	// non-template __device__ free functions DEFINED in this header. The header is now
364	// included by TWO TUs that co-reside in _ops — the scalar launcher
365	// (mega_decoder_real_adamw.cu) AND the wired TC launcher
366	// (mega_decoder_real_adamw_tc_launcher.cu, -DSG_TUNED_GEMM_IMPL=1). Without
367	// `inline` each TU emits a strong definition → "multiple definition" at host link
368	// (the template megakernels + __constant__ tables already have vague/internal
369	// linkage and never collided; only these 5 non-template defs did). `inline` lets
370	// the linker merge the identical definitions. NOT __forceinline__ — these are
371	// large (dec_backward_sample recomputes a full layer); forcing expansion is pure
372	// bloat. Single-TU JIT (the parity _tc.cu modules) is byte-identical under inline.
373	__device__ inline float dec_forward_sample(const DecWeights& w, const int* tokens_s,
374	                                     int target, DecSampleSmem* sm) {
375	    // Embedding + positional: h0[s, j] = tok[tok_s][j] + pos[s][j].
376	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
377	        const int s = idx / dec::kD, j = idx % dec::kD;
378	        sm->layer_in[0][s][j] = w.tok[(int64_t)tokens_s[s] * dec::kD + j]
379	                              + w.pos[(int64_t)s * dec::kD + j];
380	    }
381	    __syncthreads();
382	
383	    for (int li = 0; li < dec::kLayers; ++li) {
384	        const DecWeights::Layer& L = w.layer[li];
385	        float* hin = &sm->layer_in[li][0][0];   // [kSeq, kD]
386	        // qkv = hin @ in_w^T + in_b  -> [kSeq, 3d]
387	        dec_linear(hin, dec::kD, L.in_w, L.in_b, 3 * dec::kD, &sm->qkv[0][0]);
388	        // Attention per head: scores = q·k^T * scale (+ causal), softmax, ctx.
389	        // q,k,v live in qkv columns [0,d),[d,2d),[2d,3d). ctx -> sm->ctx [kSeq,d].
390	        const float scale = dec::attn_scale();
391	        // One thread per (head, qpos) computes that row's softmax + ctx slice.
392	        // kSeq*kHeads = 16 rows; threads stride. Each thread loops d_head.
393	        for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
394	            const int hh = r / dec::kSeq;     // head
395	            const int qi = r % dec::kSeq;     // query position
396	            const int qoff = hh * dec::kDhead;        // head's slice in q block
397	            const float* qrow = &sm->qkv[qi][qoff];   // [dhead]
398	            // scores over key positions kj<=qi (causal); softmax; ctx accum.
399	            float maxs = -CUDART_INF_F;
400	            float sc[dec::kSeq];
401	            #pragma unroll
402	            for (int kj = 0; kj < dec::kSeq; ++kj) {
403	                if (kj > qi) { sc[kj] = -CUDART_INF_F; continue; }
404	                const float* krow = &sm->qkv[kj][dec::kD + qoff];  // k block
405	                float dot = 0.0f;
406	                #pragma unroll
407	                for (int t = 0; t < dec::kDhead; ++t) dot += qrow[t] * krow[t];
408	                sc[kj] = dot * scale;
409	                maxs = fmaxf(maxs, sc[kj]);
410	            }
411	            float denom = 0.0f;
412	            #pragma unroll
413	            for (int kj = 0; kj < dec::kSeq; ++kj) {
414	                float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f;
415	                sc[kj] = e; denom += e;
416	            }
417	            float invd = 1.0f / denom;
418	            // store attn weights (for bwd) + compute ctx slice for this (head,qi).
419	            #pragma unroll
420	            for (int kj = 0; kj < dec::kSeq; ++kj) {
421	                float a = sc[kj] * invd;
422	                sm->attn[hh][qi][kj] = a;
423	            }
424	            // ctx[qi, hh*dhead + t] = sum_kj attn * v[kj, hh*dhead+t]
425	            #pragma unroll
426	            for (int t = 0; t < dec::kDhead; ++t) {
427	                float acc = 0.0f;
428	                #pragma unroll
429	                for (int kj = 0; kj <= qi; ++kj) {
430	                    const float vv = sm->qkv[kj][2 * dec::kD + qoff + t];
431	                    acc += sm->attn[hh][qi][kj] * vv;
432	                }
433	                sm->ctx[qi][qoff + t] = acc;
434	            }
435	        }
436	        __syncthreads();
437	        // a = ctx @ out_w^T + out_b  (reuse qkv[:, :d] as the 'a' scratch).
438	        // We need a [kSeq,d]; write into sm->x1 temporarily then add residual.
439	        dec_linear(&sm->ctx[0][0], dec::kD, L.out_w, L.out_b, dec::kD,
440	                   &sm->x1[0][0]);   // x1 holds 'a' for now
441	        // r1 = hin + a ; n1(r1) -> x1 (overwrite). Stage r1 into ff0 scratch row.
442	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
443	            const int s = idx / dec::kD, j = idx % dec::kD;
444	            sm->ctx[s][j] = hin[s * dec::kD + j] + sm->x1[s][j];  // ctx := r1
445	        }
446	        __syncthreads();
447	        dec_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
448	                          &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);
449	        // FFN: ff0 = x1 @ ff0_w^T + ff0_b ; g = gelu(ff0) ; ff2 = g @ ff2_w^T+b.
450	        dec_linear(&sm->x1[0][0], dec::kD, L.ff0_w, L.ff0_b, dec::kDff,
451	                   &sm->ff0[0][0]);
452	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kDff; idx += blockDim.x)
453	            sm->gact[idx / dec::kDff][idx % dec::kDff] =
454	                dec_gelu(sm->ff0[idx / dec::kDff][idx % dec::kDff]);
455	        __syncthreads();
456	        // ff2 -> ctx scratch (reuse), then r2 = x1 + ff2, n2(r2) -> next layer_in.
457	        dec_linear(&sm->gact[0][0], dec::kDff, L.ff2_w, L.ff2_b, dec::kD,
458	                   &sm->ctx[0][0]);   // ctx := ff2
459	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
460	            const int s = idx / dec::kD, j = idx % dec::kD;
461	            sm->ctx[s][j] = sm->x1[s][j] + sm->ctx[s][j];   // ctx := r2
462	        }
463	        __syncthreads();
464	        // n2(r2) -> output of this layer. Destination: next layer's input cache,
465	        // or the final_in buffer if this is the last layer.
466	        float* dst = (li + 1 < dec::kLayers) ? &sm->layer_in[li + 1][0][0]
467	                                             : &sm->final_in[0][0];
468	        dec_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, dst,
469	                          &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
470	    }
471	
472	    // Final norm on the LAST position only, then head → logits → NLL.
473	    // hn = norm(final_in[last]); logits = hn @ out_w^T + out_b.
474	    const float* hlast = &sm->final_in[dec::kSeq - 1][0];
475	    // LayerNorm of a single row (cooperative reduce).
476	    float sum = 0.0f;
477	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
478	    float mean = dec_block_sum(sum, sm->red) / (float)dec::kD;
479	    float vs = 0.0f;
480	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
481	        float c = hlast[j] - mean; vs += c * c;
482	    }
483	    float var = dec_block_sum(vs, sm->red) / (float)dec::kD;
484	    float inv = rsqrtf(var + dec::kLnEps);
485	    if (threadIdx.x == 0) sm->fn_inv[0] = inv;
486	    // Store hn into fn_xhat row 0's gamma/beta-applied value? We need both xhat
487	    // (for LN bwd) and hn (for head). Keep xhat in fn_xhat[last], compute hn into
488	    // x1 row 0 scratch.
489	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
490	        float xh = (hlast[j] - mean) * inv;
491	        sm->fn_xhat[dec::kSeq - 1][j] = xh;
492	        sm->x1[0][j] = xh * w.norm_w[j] + w.norm_b[j];   // x1[0] := hn
493	    }
494	    __syncthreads();
495	    // logits[o] = hn · out_w[o] + out_b[o]   (o over kVocab).
496	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
497	        const float* Wr = w.out_w + (int64_t)o * dec::kD;
498	        float acc = w.out_b[o];
499	        #pragma unroll 4
500	        for (int k = 0; k < dec::kD; ++k) acc += sm->x1[0][k] * Wr[k];
501	        sm->logits[o] = acc;
502	    }
503	    __syncthreads();
504	    // NLL (mean handled by /B in the loss reduce): logz - logits[target].
505	    float lmax = -CUDART_INF_F;
506	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
507	        lmax = fmaxf(lmax, sm->logits[o]);
508	    lmax = dec_block_max(lmax, sm->red);
509	    float es = 0.0f;
510	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
511	        es += __expf(sm->logits[o] - lmax);
512	    es = dec_block_sum(es, sm->red);
513	    float logz = lmax + __logf(es);
514	    return logz - sm->logits[target];   // sample NLL
515	}
