517	// ── Atomic-free per-CTA grad accumulation. Each dW element has a SINGLE owner
518	//    thread within the CTA across the slice's samples, so a plain += into the
519	//    CTA's partial buffer is race-free AS LONG AS the same thread owns the same
520	//    element every sample. We guarantee that by always striding output elements
521	//    by threadIdx.x with the SAME total/stride, and __syncthreads() between
522	//    samples. acc_* helpers therefore use ordinary global +=. ─────────────────
523	
524	// Recompute one layer's forward intermediates into sm (qkv, x1, ff0, gact, attn,
525	// and ctx := r2), reading from sm->layer_in[li]. Mirrors the fwd layer body but
526	// also leaves r2 in sm->ctx and x1 in sm->x1 for the backward chain.
527	__device__ inline void dec_recompute_layer(const DecWeights& w, int li,
528	                                     DecSampleSmem* sm) {
529	    const DecWeights::Layer& L = w.layer[li];
530	    float* hin = &sm->layer_in[li][0][0];
531	    dec_linear(hin, dec::kD, L.in_w, L.in_b, 3 * dec::kD, &sm->qkv[0][0]);
532	    const float scale = dec::attn_scale();
533	    for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
534	        const int hh = r / dec::kSeq, qi = r % dec::kSeq;
535	        const int qoff = hh * dec::kDhead;
536	        const float* qrow = &sm->qkv[qi][qoff];
537	        float maxs = -CUDART_INF_F; float sc[dec::kSeq];
538	        #pragma unroll
539	        for (int kj = 0; kj < dec::kSeq; ++kj) {
540	            if (kj > qi) { sc[kj] = -CUDART_INF_F; continue; }
541	            const float* krow = &sm->qkv[kj][dec::kD + qoff];
542	            float dot = 0.0f;
543	            #pragma unroll
544	            for (int t = 0; t < dec::kDhead; ++t) dot += qrow[t] * krow[t];
545	            sc[kj] = dot * scale; maxs = fmaxf(maxs, sc[kj]);
546	        }
547	        float denom = 0.0f;
548	        #pragma unroll
549	        for (int kj = 0; kj < dec::kSeq; ++kj) {
550	            float e = (kj <= qi) ? __expf(sc[kj] - maxs) : 0.0f;
551	            sc[kj] = e; denom += e;
552	        }
553	        float invd = 1.0f / denom;
554	        #pragma unroll
555	        for (int kj = 0; kj < dec::kSeq; ++kj) sm->attn[hh][qi][kj] = sc[kj] * invd;
556	        #pragma unroll
557	        for (int t = 0; t < dec::kDhead; ++t) {
558	            float acc = 0.0f;
559	            #pragma unroll
560	            for (int kj = 0; kj <= qi; ++kj)
561	                acc += sm->attn[hh][qi][kj] * sm->qkv[kj][2 * dec::kD + qoff + t];
562	            sm->ctx[qi][qoff + t] = acc;
563	        }
564	    }
565	    __syncthreads();
566	    // a -> x1 scratch, r1 -> separate; we need r1 for n1 bwd? n1 bwd needs xhat
567	    // (cached) + inv (cached); it does NOT need r1. So compute n1 fwd to fill
568	    // caches and leave x1 = n1(r1).
569	    dec_linear(&sm->ctx[0][0], dec::kD, L.out_w, L.out_b, dec::kD, &sm->x1[0][0]);
570	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
571	        const int s = idx / dec::kD, j = idx % dec::kD;
572	        sm->ctx[s][j] = hin[s * dec::kD + j] + sm->x1[s][j];   // ctx := r1
573	    }
574	    __syncthreads();
575	    dec_layernorm_fwd(&sm->ctx[0][0], L.n1_w, L.n1_b, &sm->x1[0][0],
576	                      &sm->n1_xhat[0][0], &sm->n1_inv[0], sm->red);  // x1 := n1(r1)
577	    dec_linear(&sm->x1[0][0], dec::kD, L.ff0_w, L.ff0_b, dec::kDff, &sm->ff0[0][0]);
578	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kDff; idx += blockDim.x) {
579	        const int s = idx / dec::kDff, j = idx % dec::kDff;
580	        sm->gact[s][j] = dec_gelu(sm->ff0[s][j]);
581	    }
582	    __syncthreads();
583	    // ff2 -> tmp, r2 = x1 + ff2 -> ctx (so ctx holds r2 for n2 bwd caches).
584	    // We use sm->ctx for r2; n2 caches (xhat/inv) are filled by the LN fwd below.
585	    // Stash ff2 in dh scratch (unused until bwd) to avoid clobbering x1.
586	    dec_linear(&sm->gact[0][0], dec::kDff, L.ff2_w, L.ff2_b, dec::kD, &sm->dh[0][0]);
587	    for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
588	        const int s = idx / dec::kD, j = idx % dec::kD;
589	        sm->ctx[s][j] = sm->x1[s][j] + sm->dh[s][j];   // ctx := r2
590	    }
591	    __syncthreads();
592	    // Fill n2 caches (we don't need n2's output value for bwd, only xhat/inv).
593	    // Write the (discarded) output into dh scratch.
594	    dec_layernorm_fwd(&sm->ctx[0][0], L.n2_w, L.n2_b, &sm->dh[0][0],
595	                      &sm->n2_xhat[0][0], &sm->n2_inv[0], sm->red);
596	    __syncthreads();
597	}
