599	// LayerNorm backward: given dy [kSeq,d] and cached (xhat,inv) for these
600	// positions, returns dx [kSeq,d] into dx_out, and ACCUMULATES dgamma/dbeta
601	// (summed over positions) into the CTA grad partials gw/gb [d]. Owner-thread
602	// rule for gw/gb: thread owns feature j (strided), sums over positions locally.
603	__device__ inline void dec_layernorm_bwd(
604	        const float* __restrict__ dy, const float* __restrict__ xhat,
605	        const float* __restrict__ inv, const float* __restrict__ gamma,
606	        float* __restrict__ dx_out, float* __restrict__ gw, float* __restrict__ gb,
607	        float* red, bool accum_affine) {
608	    // dgamma/dbeta: feature-parallel, sum over positions (single owner per j).
609	    if (accum_affine) {
610	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
611	            float dgw = 0.0f, dgb = 0.0f;
612	            #pragma unroll
613	            for (int s = 0; s < dec::kSeq; ++s) {
614	                float d = dy[s * dec::kD + j];
615	                dgb += d; dgw += d * xhat[s * dec::kD + j];
616	            }
617	            gw[j] += dgw; gb[j] += dgb;
618	        }
619	    }
620	    // dx per position: needs sum(dxhat) and sum(dxhat*xhat) over d (reduce).
621	    for (int s = 0; s < dec::kSeq; ++s) {
622	        const float* dyr = dy + s * dec::kD;
623	        const float* xhr = xhat + s * dec::kD;
624	        float sda = 0.0f, sdax = 0.0f;
625	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
626	            float dxhat = dyr[j] * gamma[j];
627	            sda += dxhat; sdax += dxhat * xhr[j];
628	        }
629	        sda = dec_block_sum(sda, red);
630	        sdax = dec_block_sum(sdax, red);
631	        float inv_s = inv[s];
632	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
633	            float dxhat = dyr[j] * gamma[j];
634	            dx_out[s * dec::kD + j] =
635	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
636	        }
637	        __syncthreads();
638	    }
639	}
640	
641	// dW += dY^T @ X  for a linear Y = X @ W^T + b. dY [kSeq,out], X [kSeq,in],
642	// dW [out,in]. Owner-thread rule: thread owns (o,i) output element (strided over
643	// out*in), sums over the kSeq positions locally. db[o] += sum_s dY[s,o].
644	// Also returns dX [kSeq,in] += dY @ W into dx_out (caller decides add vs set).
645	//
646	// ldY/ldX/ldDX are the ROW STRIDES (leading dimensions) of dY/X/dx_out. They
647	// are EXPLICIT (no defaults) because the smem scratch buffers this is called on
648	// are 2D arrays whose declared width (e.g. kDff=512 for ff0/gact) differs from
649	// the logical row width (out_dim/in_dim). The original packed-stride version
650	// silently read/wrote the wrong rows at both attention-seam call sites — the
651	// forward stayed exact while every grad upstream of attention was garbage
652	// (params decayed to zero via weight decay; train acc pinned at 1/97). The CPU
653	// structural mirror did NOT catch it (it indexes buffers semantically, not by
654	// flat offset), so the stride is now part of the call contract.
655	__device__ inline void dec_linear_bwd(
656	        const float* __restrict__ dY, const float* __restrict__ X,
657	        const float* __restrict__ W, int in_dim, int out_dim,
658	        float* __restrict__ dW, float* __restrict__ db,
659	        float* __restrict__ dx_out, bool set_dx,
660	        int ldY, int ldX, int ldDX) {
661	    // dW [out,in] + db [out].
662	    const int wtot = out_dim * in_dim;
663	    for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
664	        const int o = idx / in_dim, i = idx % in_dim;
665	        float acc = 0.0f;
666	        #pragma unroll
667	        for (int s = 0; s < dec::kSeq; ++s)
668	            acc += dY[s * ldY + o] * X[s * ldX + i];
669	        dW[(int64_t)o * in_dim + i] += acc;
670	    }
671	    if (db != nullptr) {
672	        for (int o = threadIdx.x; o < out_dim; o += blockDim.x) {
673	            float acc = 0.0f;
674	            #pragma unroll
675	            for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * ldY + o];
676	            db[o] += acc;
677	        }
678	    }
679	    // dX [kSeq,in] = dY @ W  (W [out,in]).
680	    const int xtot = dec::kSeq * in_dim;
681	    for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
682	        const int s = idx / in_dim, i = idx % in_dim;
683	        float acc = 0.0f;
684	        for (int o = 0; o < out_dim; ++o)
685	            acc += dY[s * ldY + o] * W[(int64_t)o * in_dim + i];
686	        if (set_dx) dx_out[s * ldDX + i] = acc;
687	        else dx_out[s * ldDX + i] += acc;
688	    }
689	    __syncthreads();
690	}
