692	// ────────────────────────────────────────────────────────────────────────────
693	//  BACKWARD for one sample (CTA-cooperative). Assumes dec_forward_sample has run
694	//  for THIS sample (so layer_in/final_in/fn caches/logits are populated and
695	//  reflect this sample). Accumulates every weight grad into the CTA's partial
696	//  buffer `g` (DecGrad over gw_cta). Uses extra smem scratch passed via sm.
697	//
698	//  Transcribed from tests/hw/decoder_oracle.py::decoder_backward.
699	// ────────────────────────────────────────────────────────────────────────────
700	__device__ inline void dec_backward_sample(const DecWeights& w, const DecGrad& g,
701	                                     const int* tokens_s, int target, int B,
702	                                     DecSampleSmem* sm) {
703	    // ── CE backward: dlogits = (softmax - onehot)/B. (logits cached in fwd.) ──
704	    float lmax = -CUDART_INF_F;
705	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
706	        lmax = fmaxf(lmax, sm->logits[o]);
707	    lmax = dec_block_max(lmax, sm->red);
708	    float es = 0.0f;
709	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
710	        es += __expf(sm->logits[o] - lmax);
711	    es = dec_block_sum(es, sm->red);
712	    float inv_es = 1.0f / es;
713	    // overwrite logits[] with dlogits in place.
714	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
715	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
716	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
717	        sm->logits[o] = dl;
718	    }
719	    __syncthreads();
720	    // ── head (out): logits = hn @ out_w^T + out_b. hn was stashed in x1[0]
721	    //    during fwd, but x1 has since been reused — recompute hn from the
722	    //    cached final-norm: hn[j] = fn_xhat[last][j]*norm_w[j] + norm_b[j]. ──
723	    // dW_out[o,:] += dlogits[o] * hn ; db_out[o] += dlogits[o].
724	    // dhn[j] = sum_o dlogits[o] * out_w[o,j].
725	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
726	        float dl = sm->logits[o];
727	        g.out_b[o] += dl;
728	        float* gwrow = g.out_w + (int64_t)o * dec::kD;
729	        const float* xh = &sm->fn_xhat[dec::kSeq - 1][0];
730	        #pragma unroll 4
731	        for (int j = 0; j < dec::kD; ++j) {
732	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
733	            gwrow[j] += dl * hn_j;
734	        }
735	    }
736	    __syncthreads();
737	    // dhn[j] (feature-parallel) into dh row 0 scratch.
738	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
739	        float acc = 0.0f;
740	        for (int o = 0; o < dec::kVocab; ++o)
741	            acc += sm->logits[o] * w.out_w[(int64_t)o * dec::kD + j];
742	        sm->dh[0][j] = acc;   // dhn
743	    }
744	    __syncthreads();
745	    // ── final norm backward: dy=dhn (row last), xhat=fn_xhat[last], inv=fn_inv.
746	    //    Produces dh_last into dh[last]; accumulate dnorm_w/dnorm_b. Use a single
747	    //    "position" (last). Build a 1-row dy view: reuse sm->ctx row last = dhn. ─
748	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x)
749	        sm->ctx[dec::kSeq - 1][j] = sm->dh[0][j];   // dy at last position
750	    __syncthreads();
751	    // dnorm_w/dnorm_b: only the last position contributes (others have dy=0).
752	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
753	        float d = sm->ctx[dec::kSeq - 1][j];
754	        float xh = sm->fn_xhat[dec::kSeq - 1][j];
755	        g.norm_b[j] += d; g.norm_w[j] += d * xh;
756	    }
757	    __syncthreads();
758	    // dx for the last position (LN backward, single row).
759	    {
760	        const float* dyr = &sm->ctx[dec::kSeq - 1][0];
761	        const float* xhr = &sm->fn_xhat[dec::kSeq - 1][0];
762	        float sda = 0.0f, sdax = 0.0f;
763	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
764	            float dxhat = dyr[j] * w.norm_w[j];
765	            sda += dxhat; sdax += dxhat * xhr[j];
766	        }
767	        sda = dec_block_sum(sda, sm->red);
768	        sdax = dec_block_sum(sdax, sm->red);
769	        float inv_s = sm->fn_inv[0];
770	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
771	            float dxhat = dyr[j] * w.norm_w[j];
772	            // dh[s,:] = 0 for s<last; last gets the LN dx.
773	            for (int s = 0; s < dec::kSeq; ++s) sm->dh[s][j] = 0.0f;
774	            sm->dh[dec::kSeq - 1][j] =
775	                inv_s * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
776	        }
777	        __syncthreads();
778	    }
779	    // dh now = grad wrt the last layer's OUTPUT [kSeq,d] (only last pos nonzero).
780	
781	    // ── per-layer backward (reverse). Each layer: recompute fwd intermediates,
782	    //    then apply the chain. We use sm scratch heavily; the running adjoint
783	    //    `dh` is preserved across the recompute (recompute writes qkv/x1/ff0/
784	    //    gact/attn/ctx + LN caches; it temporarily uses sm->dh as ff2 scratch —
785	    //    so SAVE dh into final_in (free after fwd) around the recompute). ───────
786	    for (int li = dec::kLayers - 1; li >= 0; --li) {
787	        const DecWeights::Layer& L = w.layer[li];
788	        const DecGrad::Layer& G = g.layer[li];
789	        // Save the incoming adjoint dh into final_in (unused now) — recompute
790	        // clobbers sm->dh.
791	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
792	            const int s = idx / dec::kD, j = idx % dec::kD;
793	            sm->final_in[s][j] = sm->dh[s][j];
794	        }
795	        __syncthreads();
796	        dec_recompute_layer(w, li, sm);   // fills qkv,x1,ff0,gact,attn,ctx(=r2),caches
797	        // Restore dh (grad wrt h2 = n2 output).
798	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
799	            const int s = idx / dec::kD, j = idx % dec::kD;
800	            sm->dh[s][j] = sm->final_in[s][j];
801	        }
802	        __syncthreads();
803	        // n2 backward: dh -> dr2, accumulate n2 gamma/beta. Put dr2 into ctx
804	        // (currently r2 — we no longer need r2's value, only its caches).
805	        dec_layernorm_bwd(&sm->dh[0][0], &sm->n2_xhat[0][0], &sm->n2_inv[0],
806	                          L.n2_w, &sm->ctx[0][0], G.n2_w, G.n2_b, sm->red, true);
807	        // r2 = x1 + ff2 → both branches get dr2: dx1 (residual) and dff2.
808	        // SMEM map (one layer live; values consumed before each reuse — verified
809	        // alias-safe by the structural mirror): dx1 lives in `fn_xhat` (final-norm
810	        // caches are done), dr2 stays in `ctx`. x_in = layer_in[li] is NOT touched
811	        // (in_proj bwd needs it); qkv is NOT touched (attention bwd needs q/k/v).
812	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
813	            const int s = idx / dec::kD, j = idx % dec::kD;
814	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx1 := dr2 (residual part)
815	        }
816	        __syncthreads();
817	        // ff.2 backward. dgact = dr2 @ ff2_w is needed only to form
818	        // dff0 = dgact * gelu'(ff0); since `ff0` (pre-gelu) is needed for gelu'(),
819	        // we compute dgact and immediately fold gelu' so dff0 is written OVER
820	        // `gact` (its forward value g is consumed by the dW_ff2 GEMM first). No
821	        // extra scratch buffer is needed.
822	        //   dW_ff2 += dr2^T @ g ; db_ff2 += Σ dr2.
823	        {
824	            const float* dY = &sm->ctx[0][0];   // dr2 [kSeq,d]
825	            const float* X = &sm->gact[0][0];   // g [kSeq,4d]
826	            // dW ff2 [d,4d]
827	            const int wtot = dec::kD * dec::kDff;
828	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
829	                const int o = idx / dec::kDff, i = idx % dec::kDff;
830	                float acc = 0.0f;
831	                #pragma unroll
832	                for (int s = 0; s < dec::kSeq; ++s)
833	                    acc += dY[s * dec::kD + o] * X[s * dec::kDff + i];
834	                G.ff2_w[(int64_t)o * dec::kDff + i] += acc;
835	            }
836	            for (int o = threadIdx.x; o < dec::kD; o += blockDim.x) {
837	                float acc = 0.0f;
838	                #pragma unroll
839	                for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * dec::kD + o];
840	                G.ff2_b[o] += acc;
841	            }
842	            __syncthreads();
843	            // dff0 = (dr2 @ ff2_w) * gelu'(ff0), written OVER gact.
844	            const int xtot = dec::kSeq * dec::kDff;
845	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
846	                const int s = idx / dec::kDff, i = idx % dec::kDff;
847	                float dg = 0.0f;
848	                for (int o = 0; o < dec::kD; ++o)
849	                    dg += dY[s * dec::kD + o] * L.ff2_w[(int64_t)o * dec::kDff + i];
850	                sm->gact[s][i] = dg * dec_gelu_grad(sm->ff0[s][i]);  // gact := dff0
851	            }
852	            __syncthreads();
853	        }
854	        // ff.0 backward: dY=dff0 (=gact), X=x1 -> dW ff0, db ff0, dx1 += dff0 @ ff0_w.
855	        // dx1 currently in fn_xhat (residual part); ADD the FFN path.
856	        {
857	            const float* dY = &sm->gact[0][0];   // dff0 [kSeq,4d]
858	            const float* X = &sm->x1[0][0];      // x1 [kSeq,d]
859	            const int wtot = dec::kDff * dec::kD;
860	            for (int idx = threadIdx.x; idx < wtot; idx += blockDim.x) {
861	                const int o = idx / dec::kD, i = idx % dec::kD;
862	                float acc = 0.0f;
863	                #pragma unroll
864	                for (int s = 0; s < dec::kSeq; ++s)
865	                    acc += dY[s * dec::kDff + o] * X[s * dec::kD + i];
866	                G.ff0_w[(int64_t)o * dec::kD + i] += acc;
867	            }
868	            for (int o = threadIdx.x; o < dec::kDff; o += blockDim.x) {
869	                float acc = 0.0f;
870	                #pragma unroll
871	                for (int s = 0; s < dec::kSeq; ++s) acc += dY[s * dec::kDff + o];
872	                G.ff0_b[o] += acc;
873	            }
874	            __syncthreads();
875	            const int xtot = dec::kSeq * dec::kD;
876	            for (int idx = threadIdx.x; idx < xtot; idx += blockDim.x) {
877	                const int s = idx / dec::kD, i = idx % dec::kD;
878	                float acc = 0.0f;
879	                for (int o = 0; o < dec::kDff; ++o)
880	                    acc += dY[s * dec::kDff + o] * L.ff0_w[(int64_t)o * dec::kD + i];
881	                sm->fn_xhat[s][i] += acc;   // dx1 += FFN path
882	            }
883	            __syncthreads();
884	        }
885	        // dx1 (in fn_xhat) -> n1 backward -> dr1 (into ctx). accumulate n1 g/b.
886	        dec_layernorm_bwd(&sm->fn_xhat[0][0], &sm->n1_xhat[0][0], &sm->n1_inv[0],
887	                          L.n1_w, &sm->ctx[0][0], G.n1_w, G.n1_b, sm->red, true);
888	        // r1 = x_in + a -> da = dr1 ; dx_in = dr1 (residual). dx_in accumulates
889	        // both the residual AND the attention-input path; stash dx_in into
890	        // fn_xhat (free again). da stays in ctx.
891	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
892	            const int s = idx / dec::kD, j = idx % dec::kD;
893	            sm->fn_xhat[s][j] = sm->ctx[s][j];   // dx_in := dr1 (residual)
894	        }
895	        __syncthreads();
896	        // attn out_proj backward: a = ctx_fwd @ out_w^T + out_b. But ctx_fwd
897	        // (the attention context) was overwritten by the recompute's r1/r2 reuse.
898	        // Recompute ctx_fwd from attn + v (cheap): we still have attn[] and qkv[]
899	        // (v lives in qkv[:,2d:3d]). Rebuild ctx_fwd into x1 scratch (x1 no longer
900	        // needed — ff bwd done).
901	        for (int r = threadIdx.x; r < dec::kSeq * dec::kD; r += blockDim.x) {
902	            const int qi = r / dec::kD, col = r % dec::kD;
903	            const int hh = col / dec::kDhead, t = col % dec::kDhead;
904	            float acc = 0.0f;
905	            #pragma unroll
906	            for (int kj = 0; kj <= qi; ++kj)
907	                acc += sm->attn[hh][qi][kj]
908	                     * sm->qkv[kj][2 * dec::kD + hh * dec::kDhead + t];
909	            sm->x1[qi][col] = acc;   // x1 := ctx_fwd
910	        }
911	        __syncthreads();
912	        // da is in ctx. dW_out += da^T @ ctx_fwd(x1); db_out += sum da;
913	        // dctx = da @ out_w -> store into ff0 scratch (free). dctx MUST be
914	        // written at ff0's DECLARED row stride (kDff) — passes A/B below read it
915	        // as sm->ff0[qi][col]; a packed (kD-stride) write only fills row 0's
916	        // first 512 floats and rows 1..3 read stale recomputed pre-GELU values.
917	        dec_linear_bwd(&sm->ctx[0][0], &sm->x1[0][0], L.out_w, dec::kD, dec::kD,
918	                       G.out_w, G.out_b, &sm->ff0[0][0], /*set_dx=*/true, // dctx->ff0
919	                       /*ldY=*/dec::kD, /*ldX=*/dec::kD, /*ldDX=*/dec::kDff);
920	        // ── merge-heads + attention backward (3 synced passes; the forward
921	        //    softmax weights `attn` are read by A and B and NEVER overwritten —
922	        //    dscores go to the dedicated `dsc` buffer). dctx [kSeq,d] is in ff0;
923	        //    v lives in qkv[:,2d:3d], k in qkv[:,d:2d], q in qkv[:,0:d]. dqkv is
924	        //    built into gact[:, :3d]. Transcribed from the oracle's attention bwd:
925	        //      dvh   = attn^T @ dctxh
926	        //      dattn = dctxh @ vh^T ; dscores = softmax_bwd(dattn,attn) * scale
927	        //      dqh   = dscores @ kh ; dkh = dscores^T @ qh                       ─
928	        const float scale = dec::attn_scale();
929	        // A: dv into gact[:, 2d:3d].  dv[kj,qoff+t] = Σ_{qi>=kj} attn[hh][qi][kj]
930	        //    * dctx[qi, qoff+t].  (Owner: thread per (kj, head, t).)
931	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
932	             r += blockDim.x) {
933	            const int kj = r / (dec::kHeads * dec::kDhead);
934	            const int rem = r % (dec::kHeads * dec::kDhead);
935	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
936	            const int qoff = hh * dec::kDhead;
937	            float acc = 0.0f;
938	            #pragma unroll
939	            for (int qi = kj; qi < dec::kSeq; ++qi)   // qi>=kj (causal: kj<=qi)
940	                acc += sm->attn[hh][qi][kj] * sm->ff0[qi][qoff + t];
941	            sm->gact[kj][2 * dec::kD + qoff + t] = acc;   // dv block
942	        }
943	        __syncthreads();
944	        // B: dscores into dsc.  datt[hh,qi,kj] = Σ_t dctx[qi,qoff+t]*v[kj,qoff+t];
945	        //    ds = attn*(datt - Σ_k datt*attn)*scale  (masked kj>qi → 0).
946	        for (int r = threadIdx.x; r < dec::kHeads * dec::kSeq; r += blockDim.x) {
947	            const int hh = r / dec::kSeq, qi = r % dec::kSeq;
948	            const int qoff = hh * dec::kDhead;
949	            float datt[dec::kSeq];
950	            #pragma unroll
951	            for (int kj = 0; kj < dec::kSeq; ++kj) {
952	                if (kj > qi) { datt[kj] = 0.0f; continue; }
953	                float acc = 0.0f;
954	                #pragma unroll
955	                for (int t = 0; t < dec::kDhead; ++t)
956	                    acc += sm->ff0[qi][qoff + t]
957	                         * sm->qkv[kj][2 * dec::kD + qoff + t];
958	                datt[kj] = acc;
959	            }
960	            float dot = 0.0f;
961	            #pragma unroll
962	            for (int kj = 0; kj <= qi; ++kj) dot += datt[kj] * sm->attn[hh][qi][kj];
963	            #pragma unroll
964	            for (int kj = 0; kj < dec::kSeq; ++kj) {
965	                float a = sm->attn[hh][qi][kj];
966	                sm->dsc[hh][qi][kj] = (kj <= qi) ? a * (datt[kj] - dot) * scale
967	                                                 : 0.0f;
968	            }
969	        }
970	        __syncthreads();
971	        // C: dq into gact[:,0:d], dk into gact[:,d:2d].
972	        //    dq[qi,qoff+t] = Σ_kj dsc[hh][qi][kj]*k[kj,qoff+t];
973	        //    dk[kj,qoff+t] = Σ_qi dsc[hh][qi][kj]*q[qi,qoff+t].  (Owner: pos,head,t.)
974	        for (int r = threadIdx.x; r < dec::kSeq * dec::kHeads * dec::kDhead;
975	             r += blockDim.x) {
976	            const int pos = r / (dec::kHeads * dec::kDhead);
977	            const int rem = r % (dec::kHeads * dec::kDhead);
978	            const int hh = rem / dec::kDhead, t = rem % dec::kDhead;
979	            const int qoff = hh * dec::kDhead;
980	            float dq = 0.0f, dk = 0.0f;
981	            #pragma unroll
982	            for (int kj = 0; kj < dec::kSeq; ++kj) {
983	                dq += sm->dsc[hh][pos][kj] * sm->qkv[kj][dec::kD + qoff + t];
984	                dk += sm->dsc[hh][kj][pos] * sm->qkv[kj][qoff + t];
985	            }
986	            sm->gact[pos][qoff + t] = dq;            // dq block (gact[:,0:d])
987	            sm->gact[pos][dec::kD + qoff + t] = dk;  // dk block (gact[:,d:2d])
988	        }
989	        __syncthreads();
990	        // in_proj backward: dqkv (gact[:, :3d]) -> dW in, db in, dx_in += dqkv @ in_w.
991	        // x_in = layer_in[li]. dqkv was written 2D (sm->gact[pos][col]) so dY's
992	        // row stride is gact's DECLARED width kDff — a packed (3d=384) read
993	        // walks off row 0 into the stale dff0 values left in gact[0][384:512].
994	        dec_linear_bwd(&sm->gact[0][0], &sm->layer_in[li][0][0], L.in_w,
995	                       dec::kD, 3 * dec::kD, G.in_w, G.in_b,
996	                       &sm->fn_xhat[0][0], /*set_dx=*/false,   // dx_in += attn path
997	                       /*ldY=*/dec::kDff, /*ldX=*/dec::kD, /*ldDX=*/dec::kD);
998	        // dh for the previous layer = dx_in (in fn_xhat). Move to dh.
999	        for (int idx = threadIdx.x; idx < dec::kSeq * dec::kD; idx += blockDim.x) {
1000	            const int s = idx / dec::kD, j = idx % dec::kD;
1001	            sm->dh[s][j] = sm->fn_xhat[s][j];
1002	        }
1003	        __syncthreads();
1004	    }
1005	
1006	    // ── embedding backward: dh = grad wrt h0 [kSeq,d]. tok scatter-add per token
1007	    //    id; pos sum over the sample's positions. Owner-thread rule: thread owns
1008	    //    column j; loops positions SEQUENTIALLY so colliding token ids accumulate
1009	    //    deterministically (mirrors the oracle's index_add_). ──────────────────
1010	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1011	        #pragma unroll
1012	        for (int s = 0; s < dec::kSeq; ++s) {
1013	            float d = sm->dh[s][j];
1014	            g.tok[(int64_t)tokens_s[s] * dec::kD + j] += d;   // single owner: col j
1015	            g.pos[(int64_t)s * dec::kD + j] += d;
1016	        }
1017	    }
1018	    __syncthreads();
1019	}
